import assert from "node:assert/strict";
import { once } from "node:events";
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import test from "node:test";
import { WebSerialTransport, createZKReader } from "../../web/zk-rfid-webserial.js";

// A Web Streams SerialPort peer. Frames are generated by the existing Python
// simulator through an independent Pyodide callable, not by the browser bridge.
class FakeSerialPort {
  constructor() { this.opened = false; this.writes = []; this.handler = null; }
  async open(options) {
    assert.equal(this.opened, false);
    this.opened = true;
    this.options = options;
    this.readable = new ReadableStream({ start: controller => { this.rx = controller; } });
    this.writable = new WritableStream({ write: async data => {
      this.writes.push(Uint8Array.from(data));
      await this.handler?.(data);
    } });
  }
  feed(bytes) { this.rx.enqueue(Uint8Array.from(bytes)); }
  async close() {
    assert.equal(this.readable.locked, false);
    assert.equal(this.writable.locked, false);
    this.opened = false;
  }
}

test("stream transport: fragmentation, empty chunks, close while read is pending", async () => {
  const port = new FakeSerialPort();
  const io = new WebSerialTransport(port);
  await io.open();
  await assert.rejects(io.read(0), /positive integer/);
  port.feed([]);
  port.feed([1, 2, 3]);
  assert.deepEqual([...await io.read(2)], [1, 2]);
  assert.deepEqual([...await io.read(2)], [3]);
  const pending = io.read();
  await assert.rejects(io.read(), /Concurrent/);
  await io.close();
  assert.equal((await pending).length, 0);
  assert.equal(port.opened, false);
  await io.open();
  await io.write(new Uint8Array([0, 255]));
  assert.deepEqual([...port.writes[0]], [0, 255]);
  await io.close();
});

test("a failed second owner cannot release the first owner's claim", async () => {
  const port = new FakeSerialPort();
  const first = new WebSerialTransport(port), second = new WebSerialTransport(port);
  await first.open();
  await assert.rejects(second.open(), /already owned/);
  await second.close();
  await assert.rejects(second.open(), /already owned/);
  await first.close();
  await second.open();
  await second.close();
});

test("buffered RX yields browser tasks instead of starving Stop and rendering", async () => {
  const port = new FakeSerialPort(), io = new WebSerialTransport(port);
  await io.open();
  port.feed(new Uint8Array(100000));
  await io.read(1); // Exercise the periodic yield, not just the initial one.
  let timerRan = false;
  const timer = setTimeout(() => { timerRan = true; }, 0);
  try {
    let received = 0;
    while (!timerRan && received < 100000) received += (await io.read(1)).length;
    assert(timerRan, "RX must yield to an ordinary browser task before draining a backlog");
    assert(received < 100000);
  } finally { clearTimeout(timer); await io.close(); }
});

const pyodideEntry = new URL("../../local_data/pyodide/node_modules/pyodide/pyodide.mjs", import.meta.url);

test("real Pyodide + canonical ZK SDK over Web Streams", async () => {
  const { loadPyodide } = await import(pyodideEntry.href);
  const pyodide = await loadPyodide();
  const originalFetch = globalThis.fetch;
  // Browser fetch is replaced only for file: URLs in this Node harness.
  globalThis.fetch = async (url, ...args) => String(url).startsWith("file:")
    ? new Response(await readFile(fileURLToPath(url))) : originalFetch(url, ...args);
  const reader = createZKReader({ pyodide, timeout: 0.3, antennaPorts: 4 });
  const port = new FakeSerialPort();
  let peerWrite, peerStop;
  try {
    await reader.initialize();
    pyodide.FS.writeFile("/zk_web/test_simulator.py", await readFile(new URL("../demo_app/simulator.py", import.meta.url), "utf8"));
    pyodide.globals.set("test_port", port);
    await pyodide.runPythonAsync(`
import asyncio
from pyodide.ffi import to_js
from test_simulator import DemoTransport
from zk_rfid import ZKReader
import zk_browser
assert len(zk_browser.METHODS) == 76
assert ZKReader.__module__ == "zk_rfid"
peer = DemoTransport(4)
await peer.open()
async def peer_write(data):
    return await peer.write(bytes(data.to_py()))
async def feed_rx():
    while True:
        chunk = await peer.read()
        # Exercise actual JS -> WASM conversion with every RX byte fragmented.
        for b in chunk:
            test_port.feed(to_js(bytes((b,))))
async def peer_stop():
    await peer.close()
    rx_pump.cancel()
    await asyncio.gather(rx_pump, return_exceptions=True)
rx_pump = asyncio.create_task(feed_rx())
`);
    peerWrite = pyodide.globals.get("peer_write");
    peerStop = pyodide.globals.get("peer_stop");
    port.handler = data => peerWrite(data);
    const events = [], tags = [];
    reader.addEventListener("trace", event => events.push(event.detail));
    reader.addEventListener("tag", event => tags.push(event.detail));
    await reader.connect({ port });
    assert.equal(port.options.baudRate, 115200);
    assert.equal((await reader.getReaderInfo()).outcome, "success");
    assert.deepEqual((await reader.getPower()).data, [20, 20, 20, 20]);
    await reader.setPower([17, 18, 19, 20]);
    assert.deepEqual((await reader.getPower()).data, [17, 18, 19, 20]);
    // Generic Answer sequencing is also available to the migration FastID path.
    const fastBefore = tags.length, fastWrites = port.writes.length;
    await reader.startInventory({ mode: "answer", antenna_sequence: [4, 1, 3], config: { data: "fastid", scan_time_100ms: 3 } });
    await new Promise(resolve => setTimeout(resolve, 60));
    assert.equal((await reader.stopInventory()).complete, true);
    const antennaRequests = port.writes.slice(fastWrites).filter(frame => frame[2] === 1);
    assert.deepEqual(antennaRequests.slice(0, 3).map(frame => (frame.at(-4) & 0x7F) + 1), [4, 1, 3]);
    assert(tags.length > fastBefore);
    tags.length = 0;
    // A terminal antenna error must end FastID and reach JS after Stop cleanup.
    const antennaErrorHex = pyodide.runPython('__import__("zk_rfid").append_crc(bytes.fromhex("05 00 01 F8")).hex()');
    const antennaErrorFrame = Uint8Array.from(antennaErrorHex.match(/../g), byte => parseInt(byte, 16));
    const failedWrites = port.writes.length;
    port.handler = data => data[2] === 1 ? port.feed(antennaErrorFrame) : peerWrite(data);
    const failedEvent = once(reader, "error", { signal: AbortSignal.timeout(3000) });
    await reader.startInventory({ mode: "answer", antenna_sequence: [4, 1, 3], config: { data: "fastid" } });
    const [failedFastID] = await failedEvent;
    assert.equal(failedFastID.detail.type, "DeviceError");
    assert.equal(failedFastID.detail.inventory_outcome.status, 0xF8);
    assert.equal(reader.state, "idle");
    assert.equal(port.writes.slice(failedWrites).filter(frame => frame[2] === 1).length, 1);
    const failedStop = await reader.stopInventory();
    assert.equal(failedStop.outcome, "partial");
    assert.equal(failedStop.complete, false);
    assert.equal(failedStop.status, 0xF8);
    port.handler = data => peerWrite(data);
    const oldRegion = (await reader.call("get_region")).data;
    assert.equal((await reader.getCustomRegion()).data, null);
    const custom = { start_frequency_khz: 920625, channel_count: 10, spacing_khz: 250 };
    assert.equal((await reader.setCustomRegion(custom)).outcome, "success");
    assert.deepEqual((await reader.getCustomRegion()).data, custom);
    assert.deepEqual((await reader.call("get_region")).data, custom);
    await reader.call("set_region", { region: oldRegion });
    assert.equal((await reader.getCustomRegion()).data, null);
    const originalRange = (await reader.call("get_range_control")).data;
    assert.equal(originalRange, 100);
    assert.equal((await reader.call("set_range_control", { value: 90 })).outcome, "success");
    assert.equal((await reader.call("get_range_control")).data, 90);
    await reader.call("set_range_control", { value: originalRange });
    assert.equal((await reader.call("get_range_control")).data, originalRange);
    const before = port.writes.length;
    await assert.rejects(reader.call("__getattribute__", {}), /Unknown SDK/);
    await assert.rejects(reader.call("set_baudrate", { baudrate: 57600 }), /Transport must implement/);
    await assert.rejects(reader.call("inventory_once", { config: { antenna: 5 } }), /antenna/);
    await assert.rejects(reader.call("set_range_control", { value: 101 }), /range_control/);
    await assert.rejects(reader.setCustomRegion({ ...custom, spacing_khz: 200 }), /spacing_khz/);
    assert.equal(port.writes.length, before);
    const answer = await reader.inventoryOnce({ antenna: 1, scan_time_100ms: 3 });
    assert.equal(answer.complete, true);
    assert.equal(answer.reports[0].rssi_dbm, -50);
    await reader.startInventory({ config: { antenna: 2, phase: true } });
    await new Promise(resolve => setTimeout(resolve, 120));
    const outcome = await reader.stopInventory();
    assert.equal(outcome.outcome, "success");
    assert(tags.length > 0);
    assert(tags.some(tag => tag.phase_begin_degrees != null));
    assert(tags.every(tag => tag.antenna === 2));
    // Multiple selected ports use one native Start and restore the prior mask.
    const originalMask = (await reader.call("get_antennas")).data;
    const multiBefore = port.writes.length, tagsBefore = tags.length;
    await reader.startInventory({ antenna_mask: 0b1101, config: { phase: true } });
    await new Promise(resolve => setTimeout(resolve, 120));
    assert.equal((await reader.stopInventory()).complete, true);
    assert.deepEqual([...new Set(tags.slice(tagsBefore).map(tag => tag.antenna))].sort(), [1, 3, 4]);
    assert.equal(port.writes.slice(multiBefore).filter(frame => frame[2] === 0x50).length, 1);
    assert.equal((await reader.call("get_antennas")).data, originalMask);
    assert.deepEqual((await reader.getPower()).data, [17, 18, 19, 20]);
    // Stop requested while Get Work Mode is pending must wait for Start and stop it.
    let release, entered;
    const held = new Promise(resolve => { release = resolve; });
    const queried = new Promise(resolve => { entered = resolve; });
    port.handler = async data => {
      if (data[2] === 0x77) { entered(); await held; }
      return peerWrite(data);
    };
    const starting = reader.startInventory();
    await queried;
    const stopping = reader.stopInventory();
    release();
    await starting;
    assert.equal((await stopping).complete, true);
    assert.equal(reader.state, "idle");
    port.handler = data => peerWrite(data);
    assert(events.some(event => event.kind === "tx"));
    assert(events.some(event => event.kind === "frame"));
    const written = await reader.writeEpc({ targetEpc: answer.reports[0].epc, newEpc: "ABCD0001" });
    assert.equal(written.confirmation, "read_back_verified");
    assert.equal(written.steps.length, 3);
    assert.equal(written.outcome, "success");
    // A negative native result is preserved, not mislabeled as transport success.
    await pyodide.runPythonAsync('peer.inject = "device_error"');
    const failed = await reader.getReaderInfo();
    assert.equal(failed.outcome, "failure");
    assert.equal(failed.status, 0xF9);
    await pyodide.runPythonAsync('peer.inject = "tag_error"');
    const tagError = await reader.call("read_memory", { bank: 3, word_address: 0, word_count: 1 });
    assert.equal(tagError.status, 0xFC);
    assert.equal(tagError.tag_error, 4);
    await pyodide.runPythonAsync('peer.inject = "partial"');
    const partial = await reader.setPower(20, true);
    assert.equal(partial.outcome, "partial");
    assert.equal(partial.status, 0x13);
    // Stop remains callable while a managed Answer loop owns the command lock.
    await reader.startInventory({ mode: "answer", config: { scan_time_100ms: 3 } });
    await new Promise(resolve => setTimeout(resolve, 50));
    const stopped = await reader.disconnect();
    assert.equal(stopped.inventory_outcome.outcome, "success");
    assert.equal(port.opened, false);
    await reader.connect({ port });
    await pyodide.runPythonAsync('peer.inject = "timeout"');
    const writesBeforeTimeout = port.writes.length;
    const unknown = await reader.call("write_memory", {
      bank: 3, word_address: 0, data: "AABB", target: { epc: "ABCD0001" },
    });
    assert.equal(unknown.outcome, "unknown");
    assert.equal(unknown.confirmation, "transmitted");
    assert.equal(reader.state, "unknown");
    assert.equal(port.writes.length, writesBeforeTimeout + 1, "uncertain writes must not be retried");
    const unknownStop = await reader.stopInventory();
    assert.equal(unknownStop.outcome, "unknown");
    assert.equal(unknownStop.complete, false);
    assert.equal(unknownStop.termination_reason, "stop_unconfirmed");
    assert.equal(reader.state, "unknown");
    assert.equal(port.writes.length, writesBeforeTimeout + 1, "Stop must not guess a mode after timeout");
    await assert.rejects(reader.getReaderInfo(), /resynchronization/);
    await reader.disconnect();
    await assert.rejects(reader.connect({ port }), /recover: true/);
    await reader.connect({ port, recover: true });
    await reader.disconnect();
    await reader.connect({ port });
    port.rx.error(new Error("USB disconnected"));
    await new Promise(resolve => setTimeout(resolve, 30));
    assert.equal(reader.state, "unknown");
    await reader.disconnect().catch(() => {});
    await assert.rejects(reader.connect({ port }), /recover: true/);
    await reader.connect({ port, recover: true });
    await reader.disconnect();
    // Cleanup errors also require a known clean boundary before reusing a port.
    await reader.connect({ port });
    const close = port.close.bind(port);
    port.close = async () => { await close(); throw new Error("USB close failed"); };
    await assert.rejects(reader.disconnect(), /Could not fully close/);
    port.close = close;
    assert.equal(port.opened, false);
    await assert.rejects(reader.connect({ port }), /recover: true/);
    await reader.connect({ port, recover: true });
    await reader.disconnect();
    await pyodide.runPythonAsync('assert not [t for t in asyncio.all_tasks() if t.get_name() == "zk-rfid-rx" and not t.done()]');
  } finally {
    await reader.disconnect().catch(() => {});
    if (peerStop) await peerStop();
    peerWrite?.destroy();
    peerStop?.destroy();
    pyodide.globals.delete("test_port");
    globalThis.fetch = originalFetch;
  }
});
